typedef float time_value_t;
typedef unsigned char uint8;
typedef unsigned int uint32;

class string_buf;
class stringx
{
protected:
    char *chars;
    string_buf *my_buf;
public:
    stringx();
    stringx(const stringx &);
    ~stringx();
    stringx &operator=(const stringx &);
};

class color32
{
public:
    union {
        struct { uint8 b, g, r, a; } c;
        uint32 i;
    };
};

class Font
{
public:
    enum HORIZJUST { HORIZJUST_LEFT, HORIZJUST_CENTER, HORIZJUST_RIGHT };
    enum VERTJUST { VERTJUST_TOP, VERTJUST_CENTER, VERTJUST_BOTTOM };
};

int nglGetScreenWidth();
int nglGetScreenHeight();

template <class T> void adjustCoords(T &x, T &y)
{
    x = (T) (x*(nglGetScreenWidth()/640.f));
    y = (T) (y*(nglGetScreenHeight()/480.f));
}

class TextString
{
protected:
    Font* font;
    stringx text;
    float x;
    float y;
    int z;
    Font::HORIZJUST hJustify;
    Font::VERTJUST vJustify;
    bool even_number_spacing;
    int fade;
    float fade_alpha;
    float fade_timer;
    float scale;
    float button_scale;
    bool override_alpha;

public:
    bool checkTime;
    float time;
    bool no_color;
    color32 color;

    virtual ~TextString();
    virtual void Update(time_value_t time_inc);
    virtual void Draw();
    virtual void setHJustify(const Font::HORIZJUST hjust);
    virtual void setVJustify(const Font::VERTJUST vjust);
    virtual void setFont(Font * f);
    virtual void setButtonScale(float bs);
    virtual void numberSpacing(bool on);
    virtual void changeText(stringx t);
    virtual void changeScale(const float s);
    virtual void changePos(float posx, float posy);
    virtual void changeX(const float posX);
    virtual void changeY(const float posY);
    virtual void changeZ(int _z);
    virtual void ChangeFade(bool start, bool fade_in, float time=2.0f);
    virtual void SetFade(const float a);
    virtual float getX();
    virtual float getY();
    virtual int getZ();
    virtual stringx getText();
    virtual float GetScale(void) const;
    virtual float GetButtonScale(void) const;
    virtual bool GetNumberSpacing(void) const;
    virtual Font * GetFont(void);
    virtual Font::HORIZJUST GetHJustify(void) const;
    virtual Font::VERTJUST GetVJustify(void) const;
};

class BurstText : public TextString
{
protected:
    static float TARGET_SCALE;
    static float TARGET_SCALE_TIME;
    static float TARGET_ALPHA_TIME;
    float targetScale;
    float scaleRate;

public:
    void Burst(TextString * orig);
};

void BurstText::Burst(TextString * orig)
{
    text = orig->getText();
    time = orig->time;
    checkTime = orig->checkTime;
    x = orig->getX();
    y = orig->getY();
    adjustCoords(x, y);
    z = orig->getZ();
    button_scale = orig->GetButtonScale();
    no_color = orig->no_color;
    color = orig->color;
    font = orig->GetFont();
    even_number_spacing = orig->GetNumberSpacing();
    hJustify = orig->GetHJustify();
    vJustify = orig->GetVJustify();

    ChangeFade(true, false, TARGET_ALPHA_TIME);
    scale = orig->GetScale();
    targetScale = scale*TARGET_SCALE;
    scaleRate = TARGET_SCALE_TIME;
}
